package main

import (
	"strings"
	"unicode/utf8"

	"github.com/jterrazz/studio-station/src/catalog"
)

const footprintPath = "docs/reference/footprint.md"

const footprintPreamble = `# Footprint

<!-- GENERATED by ` + "`make generate`" + ` from src/catalog: DO NOT EDIT -->

Everything ` + "`station`" + ` and the catalogue's tools write on a machine, by level. The levels, the relocation rule and the commands that clean and reset are [Storage](storage.md)'s.

` + "%LEVELS%" + `

Paths under ` + "`~/.config`, `~/.local/share`, `~/.local/state` and `~/.cache`" + ` follow their ` + "`XDG_*_HOME`" + ` variable when it is set and absolute. A path marked mac lives on a host and a macOS VM; linux, on a Linux VM; vm, in every VM and never on a host; host, on a host only.`

func footprint() string {
	levels := table([]string{"Level", "Who removes it"}, [][]string{
		{"cache", "`station storage clean`, with no question"},
		{"data", "`station storage reset <tool>`, named and confirmed"},
		{"config", "nobody: a config item's uninstall where reversible"},
		{"kept", "nobody"},
	})
	parts := []string{
		strings.Replace(footprintPreamble, "%LEVELS%", levels, 1),
		"## Station", table([]string{"Path", "Level", "Note"}, storedRows(catalog.StationStorage)), catalog.StationRetiredNote,
		"## Tools",
	}
	for _, t := range catalog.Tools {
		if !t.Storage.Declared() {
			continue
		}
		parts = append(parts, "### "+t.Name, table([]string{"Path", "Level", "Note"}, storedRows(t.Storage)))
		if lines := actionLines(t.Storage); lines != "" {
			parts = append(parts, lines)
		}
	}
	parts = append(parts,
		"## Config items", table([]string{"Item", "Path", "Level", "Note"}, configRows()),
		"## Home-root exceptions", "What a tool keeps at the root of the home folder, declared with its reason; anything else there is a stray.", table([]string{"Path", "Reason"}, exceptionRows()),
		"## Relocations", "Written by `station setup` into the tool's own file, never by a shell variable.", table([]string{"Tool", "File", "Key", "Value", "Status"}, relocationRows()),
	)
	return strings.Join(parts, "\n\n") + "\n"
}

func shown(pattern string) string {
	for prefix, root := range map[string]string{"{config}": "~/.config", "{data}": "~/.local/share", "{state}": "~/.local/state", "{cache}": "~/.cache"} {
		if rest, ok := strings.CutPrefix(pattern, prefix); ok {
			return root + rest
		}
	}
	return pattern
}

func code(s string) string { return "`" + s + "`" }

func on(kinds []catalog.MachineKind) string {
	has := map[catalog.MachineKind]bool{}
	for _, k := range kinds {
		has[k] = true
	}
	switch {
	case len(has) == 0 || len(has) == 3:
		return ""
	case len(has) == 2 && has[catalog.Host] && has[catalog.MacOS]:
		return "mac"
	case len(has) == 2 && has[catalog.Linux] && has[catalog.MacOS]:
		return "vm"
	case len(has) == 1 && has[catalog.Linux]:
		return "linux"
	case len(has) == 1 && has[catalog.Host]:
		return "host"
	case len(has) == 1 && has[catalog.MacOS]:
		return "macOS VM"
	}
	return "host and Linux VM"
}

func note(parts ...string) string {
	var kept []string
	for _, p := range parts {
		if p != "" {
			kept = append(kept, p)
		}
	}
	return strings.Join(kept, "; ")
}

func memoNote(memos []string) string {
	if len(memos) == 0 {
		return ""
	}
	shownMemos := make([]string, 0, len(memos))
	for _, m := range memos {
		shownMemos = append(shownMemos, code(m))
	}
	return strings.Join(shownMemos, ", ") + " rewritten on every call, not counted"
}

func storedRows(s catalog.Storage) [][]string {
	rows := make([][]string, 0, len(s.Paths)+len(s.Installed)+len(s.Strays))
	for _, p := range s.Paths {
		rows = append(rows, []string{code(shown(p.Path)), string(p.Level), note(on(p.On), p.Note, memoNote(p.Memos))})
	}
	for _, p := range s.Installed {
		removal := s.Removal[p]
		if removal == "" {
			removal = "removed by `station tools uninstall`"
		}
		rows = append(rows, []string{code(shown(p)), "installed", removal})
	}
	for _, st := range s.Strays {
		moves := make([]string, 0, len(st.Move))
		for _, m := range st.Move {
			moves = append(moves, code(shown(m.From))+" to "+code(shown(m.To)))
		}
		detail := "stray: `station storage clean` empties it"
		if len(moves) > 0 {
			detail = "stray: `station setup` moves " + strings.Join(moves, ", ")
		}
		rows = append(rows, []string{code(st.Path), "stray", detail})
	}
	return rows
}

func actionLines(s catalog.Storage) string {
	var lines []string
	if c := actions(s.Clean); c != "" {
		lines = append(lines, "Clean: "+c+".")
	}
	if r := actions(s.Reset); r != "" {
		lines = append(lines, "Reset: "+r+".")
	} else if s.NoReset != "" {
		lines = append(lines, "Reset: none ("+s.NoReset+").")
	}
	if s.Quit != "" {
		lines = append(lines, "A reset refuses while "+code(s.Quit)+" runs.")
	}
	return strings.Join(lines, " ")
}

func actions(list []catalog.Action) string {
	var out []string
	for _, a := range list {
		if len(a.Run) > 0 {
			run := code(strings.Join(a.Run, " "))
			if a.Exists != "" {
				run += " when " + code(shown(a.Exists)) + " exists"
			}
			out = append(out, run)
		}
		for _, d := range a.Delete {
			out = append(out, "delete "+code(shown(d)))
		}
	}
	return strings.Join(out, ", ")
}

func configRows() [][]string {
	var rows [][]string
	for _, it := range catalog.ConfigItems {
		writes := it.Writes
		if d, ok := it.Effect.(catalog.Dotfiles); ok {
			for _, c := range d.Files {
				writes = append(writes, catalog.Stored{Path: c.To, Level: catalog.LevelConfig, Note: "the embedded " + code(c.From)})
			}
		}
		if t, ok := it.Effect.(catalog.Touch); ok && len(writes) == 0 {
			writes = append(writes, catalog.Stored{Path: t.Path, Level: catalog.LevelConfig})
		}
		for _, w := range writes {
			rows = append(rows, []string{it.Name, code(shown(w.Path)), string(w.Level), w.Note})
		}
	}
	return rows
}

func exceptionRows() [][]string {
	rows := make([][]string, 0, len(catalog.HomeExceptions))
	for _, e := range catalog.HomeExceptions {
		rows = append(rows, []string{code("~/" + e.Path), e.Reason})
	}
	return rows
}

func relocationRows() [][]string {
	var rows [][]string
	for _, t := range catalog.Tools {
		for _, r := range t.Storage.Relocate {
			status := "written"
			if r.Pending != "" {
				status = "pending: " + r.Pending
			}
			rows = append(rows, []string{t.Name, string(r.File), code(r.Key), code(shown(r.Value)), status})
		}
	}
	return rows
}

func table(header []string, rows [][]string) string {
	all := append([][]string{header}, rows...)
	widths := make([]int, len(header))
	for _, row := range all {
		for i, cell := range row {
			widths[i] = max(widths[i], utf8.RuneCountInString(cell), 3)
		}
	}
	lines := make([]string, 0, len(all)+1)
	for i, row := range all {
		cells := make([]string, len(row))
		for j, cell := range row {
			cells[j] = pad(cell, widths[j])
		}
		lines = append(lines, "| "+strings.Join(cells, " | ")+" |")
		if i == 0 {
			dashes := make([]string, len(header))
			for j := range header {
				dashes[j] = strings.Repeat("-", widths[j])
			}
			lines = append(lines, "| "+strings.Join(dashes, " | ")+" |")
		}
	}
	return strings.Join(lines, "\n")
}
